<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';require_admin();$categories=['material'=>'Material','manutencao'=>'Manutenção','energia'=>'Energia','funcionarios'=>'Funcionários','transporte'=>'Transporte','aluguel'=>'Aluguel','impostos'=>'Impostos','outros'=>'Outros'];
if(is_post()){validate_csrf($_POST['csrf_token']??null);$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);$user=current_user();try{if($action==='save'){$desc=trim((string)($_POST['descricao']??''));$cat=(string)($_POST['categoria']??'');$value=money_to_float((string)($_POST['valor']??''));$date=(string)($_POST['data_despesa']??'');if(mb_strlen($desc)<2||!isset($categories[$cat])||$value<=0||!DateTime::createFromFormat('Y-m-d',$date))throw new RuntimeException('Preencha descrição, categoria, valor e data corretamente.');if($id){$s=db()->prepare('SELECT * FROM despesas WHERE id=?');$s->execute([$id]);$before=$s->fetch();if(!$before)throw new RuntimeException('Despesa não encontrada.');db()->prepare('UPDATE despesas SET descricao=?,categoria=?,valor=?,data_despesa=?,observacao=? WHERE id=?')->execute([$desc,$cat,$value,$date,trim((string)($_POST['observacao']??''))?:null,$id]);audit('edicao','despesa',$id,$before,['descricao'=>$desc,'valor'=>$value]);flash('success','Despesa atualizada.');}else{db()->prepare('INSERT INTO despesas (descricao,categoria,valor,data_despesa,observacao,criado_por_id) VALUES (?,?,?,?,?,?)')->execute([$desc,$cat,$value,$date,trim((string)($_POST['observacao']??''))?:null,$user['id']]);$id=(int)db()->lastInsertId();audit('criacao','despesa',$id,null,['descricao'=>$desc,'valor'=>$value]);notify_role('administrador','Despesa adicionada',$desc.' · '.money($value),null,'financeiro');flash('success','Despesa adicionada.');}}elseif($action==='cancel'){$s=db()->prepare('SELECT * FROM despesas WHERE id=? AND status="ativa"');$s->execute([$id]);$before=$s->fetch();if(!$before)throw new RuntimeException('Despesa não encontrada ou já cancelada.');db()->prepare('UPDATE despesas SET status="cancelada",cancelado_em=NOW(),cancelado_por_id=? WHERE id=?')->execute([$user['id'],$id]);audit('cancelamento','despesa',$id,$before,['status'=>'cancelada']);flash('success','Despesa cancelada.');}else throw new RuntimeException('Ação inválida.');}catch(Throwable $e){error_log('Despesa: '.$e->getMessage());flash('error',$e instanceof RuntimeException?$e->getMessage():'Não foi possível salvar a despesa.');}redirect('admin/despesas.php');}
$from=$_GET['inicio']??date('Y-m-01');$to=$_GET['fim']??date('Y-m-d');$cat=$_GET['categoria']??'';$sql='SELECT d.*,u.nome FROM despesas d JOIN usuarios u ON u.id=d.criado_por_id WHERE d.data_despesa BETWEEN ? AND ?';$params=[$from,$to];if(isset($categories[$cat])){$sql.=' AND d.categoria=?';$params[]=$cat;}$sql.=' ORDER BY d.data_despesa DESC,d.id DESC';$s=db()->prepare($sql);$s->execute($params);$expenses=$s->fetchAll();$total=array_sum(array_map(fn($d)=>(float)($d['status']==='ativa'?$d['valor']:0),$expenses));$edit=null;if(!empty($_GET['editar'])){$s=db()->prepare('SELECT * FROM despesas WHERE id=?');$s->execute([(int)$_GET['editar']]);$edit=$s->fetch()?:null;}
$page_title='Despesas';require_once __DIR__ . '/../includes/header.php';
?>
<div class="grid two-col"><section class="card form-card"><div class="section-heading"><div><h2><?=$edit?'Editar despesa':'Nova despesa'?></h2><p>Alterações ficam registradas na auditoria.</p></div></div><form method="post"><?=csrf_input()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0)?>"><div class="form-grid"><label class="full">Descrição<input name="descricao" value="<?=e($edit['descricao']??'')?>" required></label><label>Categoria<select name="categoria" required><?php foreach($categories as $key=>$label):?><option value="<?=e($key)?>" <?=($edit['categoria']??'')===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label>Valor<input name="valor" data-money value="<?=isset($edit)?e(number_format($edit['valor'],2,',','.')):''?>" required></label><label>Data<input type="date" name="data_despesa" value="<?=e($edit['data_despesa']??date('Y-m-d'))?>" required></label><label class="full">Observação<textarea name="observacao"><?=e($edit['observacao']??'')?></textarea></label></div><div class="form-actions"><?php if($edit):?><a class="btn btn-secondary" href="<?=e(url('admin/despesas.php'))?>">Cancelar edição</a><?php endif;?><button class="btn btn-primary">Salvar despesa</button></div></form></section><section class="card card-pad"><small class="text-muted">Total no período filtrado</small><h2><?=money($total)?></h2><p class="text-muted">Despesas canceladas continuam visíveis no histórico, mas não entram no total.</p></section></div>
<form class="card filters no-print" method="get"><label>De<input type="date" name="inicio" value="<?=e($from)?>"></label><label>Até<input type="date" name="fim" value="<?=e($to)?>"></label><label>Categoria<select name="categoria"><option value="">Todas</option><?php foreach($categories as $key=>$label):?><option value="<?=e($key)?>" <?=$cat===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><button class="btn btn-secondary btn-small">Filtrar</button></form>
<section class="card card-pad"><div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Descrição</th><th>Categoria</th><th>Valor</th><th>Status</th><th class="no-print">Ações</th></tr></thead><tbody><?php foreach($expenses as $d):?><tr><td><?=date_br($d['data_despesa'])?></td><td><strong><?=e($d['descricao'])?></strong><br><small class="text-muted"><?=e($d['nome'])?></small></td><td><?=e($categories[$d['categoria']])?></td><td><?=money($d['valor'])?></td><td><?= $d['status']==='ativa'?'<span class="badge badge-pago">Ativa</span>':'<span class="badge badge-cancelado">Cancelada</span>'?></td><td class="no-print"><div class="button-row"><?php if($d['status']==='ativa'):?><a class="btn btn-secondary btn-small" href="?<?=e(http_build_query(['inicio'=>$from,'fim'=>$to,'categoria'=>$cat,'editar'=>$d['id']]))?>">Editar</a><form method="post"><?=csrf_input()?><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?=$d['id']?>"><button class="btn btn-danger btn-small" data-confirm="Cancelar esta despesa?">Cancelar</button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$expenses):?><tr><td colspan="6"><div class="empty-state">Nenhuma despesa no período.</div></td></tr><?php endif;?></tbody></table></div></section>
<?php require_once __DIR__ . '/../includes/footer.php'; ?>
